    "description": "Limpiador Portátil De Vidrio Ventanas Magnéticos Triangular Este sistema cuenta con un doble sistema de limpieza: la esponja enjabona, desengrasa, y lava el cristal, acabando con la suciedad y el filo va secando y escurriendo la parte lavada. Quedando por fuera y dentro totalmente seco. El dispositivo gemelo, limpia él solo la parte exterior del cristal, limpia como siempre lo haces desde la parte interior de tu casa, departamento u oficina. No temas que al limpiar el lado que está fuera se caiga, ya que sus potentes imanes mantendrán unidos ambos dispositivos. Viene provisto de una cuerda como elemento adicional de seguridad. Sencillo, original, ingenioso y muy efectivo. La forma más fácil de limpiar tus vidrios, por las dos caras sin esfuerzo y al toque y sin tener que contratar personal de limpieza, usar andamios, escaleras, escobas con trapos. Ahorra tiempo mientras que limpias una cara, la cara exterior se limpiará sola, eso significa la mitad de esfuerzo. Material: plástico + imán + goma + esponja Tamaño: aprox. 13,5*16*6 cm Rango de aplicación: vidrio de 5-12mm, 3-8mmVidrio Este limpiador de vidrios magnético está diseñado principalmente para vidrios simples (delgados). No es apto para ventanas de doble vidrio, ya que el imán no tiene la fuerza suficiente para adherirse correctamente entre ambos paneles. Si tus ventanas son de doble vidrio, vidrio templado grueso o cuentan con cámara de aire, te recomendamos verificar el grosor antes de comprar para asegurar un uso adecuado.",
